"""0029 office head picker: a login may have no office yet (`users.office_id` and `users.role` nullable)

Design `office-head-picker` ("Data"; decisions 15-16); docs/schema/schema.md, row `users`. The design names it 0029
"if row 157's 0028 merges first", which it did. Autogenerated against the dev database (it found the two NULL
changes), then the CHECK and the downgrade guard were written by hand: autogenerate does not compare CHECK
constraints. No data changes, no table, type, trigger or grant changes (`aslms_app` already has SELECT / INSERT /
UPDATE on `users`).

Upgrade:
1. `users.office_id` and `users.role` DROP NOT NULL: NULL only for a login created with no office yet, until its first
   membership writes the mirror.
2. CHECK `ck_users_placed` ((office_id IS NULL) = (role IS NULL)) keeps the pair together.

Downgrade: refused, naming the count, while any login has no office yet (no value is invented); otherwise the CHECK
is dropped and NOT NULL restored.

Revision ID: 0029
Revises: 0028
Create Date: 2026-10-26
"""

from __future__ import annotations

import sqlalchemy as sa
from alembic import op

revision = "0029"
down_revision = "0028"
branch_labels = None
depends_on = None

CHECK = "ck_users_placed"


def upgrade() -> None:
    op.alter_column("users", "office_id", existing_type=sa.UUID(), nullable=True)
    op.alter_column("users", "role", existing_type=sa.VARCHAR(length=40), nullable=True)
    op.create_check_constraint(op.f(CHECK), "users", "(office_id IS NULL) = (role IS NULL)")


def downgrade() -> None:
    bind = op.get_bind()
    waiting = int(bind.execute(sa.text("SELECT count(*) FROM users WHERE office_id IS NULL")).scalar() or 0)
    if waiting:
        raise RuntimeError(
            f"0029 downgrade refused: {waiting} login(s) have no office yet; add each one to an office first "
            "(the downgrade invents no office or type)"
        )
    op.drop_constraint(op.f(CHECK), "users", type_="check")
    op.alter_column("users", "role", existing_type=sa.VARCHAR(length=40), nullable=False)
    op.alter_column("users", "office_id", existing_type=sa.UUID(), nullable=False)
